-- H2 mirror of src/main/resources/db/migration. Flyway is off in tests; update this with every migration.
-- V1__create_users.sql
CREATE TABLE users (id BIGINT GENERATED BY DEFAULT AS IDENTITY (START WITH 2) PRIMARY KEY, display_name VARCHAR(100) NOT NULL, email VARCHAR(255) NOT NULL, created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP, CONSTRAINT uq_users_email UNIQUE (email));
INSERT INTO users (id, display_name, email) VALUES (1, 'Default user', 'default-user@study-track.local');
-- V2__create_subjects_topics.sql (TEXT columns are VARCHAR here so Hibernate validation sees the same type as PostgreSQL)
CREATE TABLE subjects (id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, user_id BIGINT NOT NULL REFERENCES users (id), name VARCHAR(120) NOT NULL, description VARCHAR(1000), icon VARCHAR(16), sort_order INT NOT NULL DEFAULT 0, archived BOOLEAN NOT NULL DEFAULT FALSE, created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP, updated_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP, CONSTRAINT uq_subjects_user_name UNIQUE (user_id, name));
CREATE TABLE topics (id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, subject_id BIGINT NOT NULL REFERENCES subjects (id) ON DELETE CASCADE, parent_id BIGINT REFERENCES topics (id) ON DELETE CASCADE, name VARCHAR(200) NOT NULL, description_html VARCHAR(1000000), sort_order INT NOT NULL DEFAULT 0, created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP, updated_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP, CONSTRAINT ck_topics_not_own_parent CHECK (parent_id IS NULL OR parent_id <> id));
CREATE INDEX idx_topics_subject_id ON topics (subject_id);
CREATE INDEX idx_topics_parent_id ON topics (parent_id);
-- V3__create_items.sql
CREATE TABLE study_items (id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, topic_id BIGINT NOT NULL REFERENCES topics (id) ON DELETE CASCADE, item_type VARCHAR(20) NOT NULL, title VARCHAR(300) NOT NULL, question_html VARCHAR(1000000), answer_html VARCHAR(1000000), notes_html VARCHAR(1000000), answer_plain VARCHAR(1000000), difficulty VARCHAR(10) NOT NULL DEFAULT 'MEDIUM', source VARCHAR(10) NOT NULL DEFAULT 'MANUAL', import_job_id BIGINT, content_hash VARCHAR(64), sort_order INT NOT NULL DEFAULT 0, created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP, updated_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP, CONSTRAINT ck_study_items_type CHECK (item_type IN ('QUESTION', 'NOTE', 'EXAMPLE', 'DIAGRAM')), CONSTRAINT ck_study_items_difficulty CHECK (difficulty IN ('EASY', 'MEDIUM', 'HARD')), CONSTRAINT ck_study_items_source CHECK (source IN ('MANUAL', 'IMPORT')));
CREATE INDEX idx_study_items_topic_id ON study_items (topic_id);
CREATE INDEX idx_study_items_content_hash ON study_items (content_hash);
CREATE TABLE tags (id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, user_id BIGINT NOT NULL REFERENCES users (id), name VARCHAR(50) NOT NULL, CONSTRAINT uq_tags_user_name UNIQUE (user_id, name));
CREATE TABLE study_item_tags (item_id BIGINT NOT NULL REFERENCES study_items (id) ON DELETE CASCADE, tag_id BIGINT NOT NULL REFERENCES tags (id) ON DELETE CASCADE, CONSTRAINT pk_study_item_tags PRIMARY KEY (item_id, tag_id));
CREATE INDEX idx_study_item_tags_tag_id ON study_item_tags (tag_id);
-- V4__create_media.sql
CREATE TABLE media_files (id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, user_id BIGINT NOT NULL REFERENCES users (id), item_id BIGINT REFERENCES study_items (id) ON DELETE SET NULL, original_name VARCHAR(255) NOT NULL, content_type VARCHAR(100) NOT NULL, size_bytes BIGINT NOT NULL, storage_key VARCHAR(500) NOT NULL, width INT, height INT, alt_text VARCHAR(500), created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP, CONSTRAINT uq_media_files_storage_key UNIQUE (storage_key), CONSTRAINT ck_media_files_size CHECK (size_bytes > 0));
CREATE INDEX idx_media_files_user_id ON media_files (user_id);
CREATE INDEX idx_media_files_item_id ON media_files (item_id);
-- V5__create_progress.sql
CREATE TABLE item_progress (id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, user_id BIGINT NOT NULL REFERENCES users (id), item_id BIGINT NOT NULL REFERENCES study_items (id) ON DELETE CASCADE, status VARCHAR(20) NOT NULL DEFAULT 'NOT_STARTED', confidence SMALLINT, review_count INT NOT NULL DEFAULT 0, last_reviewed_at TIMESTAMP, next_review_at TIMESTAMP, bookmarked BOOLEAN NOT NULL DEFAULT FALSE, updated_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP, CONSTRAINT uq_item_progress_user_item UNIQUE (user_id, item_id), CONSTRAINT ck_item_progress_status CHECK (status IN ('NOT_STARTED', 'LEARNING', 'DONE')), CONSTRAINT ck_item_progress_confidence CHECK (confidence IS NULL OR confidence BETWEEN 1 AND 5), CONSTRAINT ck_item_progress_review_count CHECK (review_count >= 0));
CREATE INDEX idx_item_progress_item_id ON item_progress (item_id);
CREATE INDEX idx_item_progress_user_next_review ON item_progress (user_id, next_review_at);
CREATE TABLE topic_progress (id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, user_id BIGINT NOT NULL REFERENCES users (id), topic_id BIGINT NOT NULL REFERENCES topics (id) ON DELETE CASCADE, completed BOOLEAN NOT NULL DEFAULT FALSE, completed_at TIMESTAMP, CONSTRAINT uq_topic_progress_user_topic UNIQUE (user_id, topic_id));
CREATE INDEX idx_topic_progress_topic_id ON topic_progress (topic_id);
CREATE TABLE review_log (id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, user_id BIGINT NOT NULL REFERENCES users (id), item_id BIGINT NOT NULL REFERENCES study_items (id) ON DELETE CASCADE, result VARCHAR(10) NOT NULL, reviewed_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP, CONSTRAINT ck_review_log_result CHECK (result IN ('AGAIN', 'HARD', 'GOOD', 'EASY')));
CREATE INDEX idx_review_log_user_reviewed_at ON review_log (user_id, reviewed_at);
CREATE INDEX idx_review_log_item_id ON review_log (item_id, reviewed_at);
CREATE TABLE study_sessions (id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, user_id BIGINT NOT NULL REFERENCES users (id), subject_id BIGINT NOT NULL REFERENCES subjects (id) ON DELETE CASCADE, last_topic_id BIGINT REFERENCES topics (id) ON DELETE SET NULL, last_item_id BIGINT REFERENCES study_items (id) ON DELETE SET NULL, updated_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP, CONSTRAINT uq_study_sessions_user_subject UNIQUE (user_id, subject_id));
CREATE INDEX idx_study_sessions_user_updated_at ON study_sessions (user_id, updated_at);
